  function permutationCount(n, r) {
    if (r < 0 || r > n) return 0;
    let value = 1;
    for (let k = 0; k < r; k += 1) value *= n - k;
    return value;
  }

  function repeatedPermutationCount(total, counts) {
    return factorialCount(total) / counts.reduce((acc, value) => acc * factorialCount(value), 1);
  }

  function countMultisetLengthSelections(counts, length) {
    let total = 0;
    function walk(index, remain) {
      if (index === counts.length) {
        if (remain === 0) total += 1;
        return;
      }
      for (let use = 0; use <= Math.min(counts[index], remain); use += 1) {
        walk(index + 1, remain - use);
      }
    }
    walk(0, length);
    return total;
  }

  function gridPathCount(right, up) {
    return combinationCount(right + up, right);
  }

  function gridPathViaCount(right, up, point) {
    const [x, y] = point;
    if (x < 0 || y < 0 || x > right || y > up) return 0;
    return gridPathCount(x, y) * gridPathCount(right - x, up - y);
  }

  function gridPathAvoidCount(right, up, point) {
    return gridPathCount(right, up) - gridPathViaCount(right, up, point);
  }

