  function buildS312DoubleFromSingleSubtypeSet(count) { return buildS312DoubleFromSingleSet(count); }
  function buildS312HalfAngleKnownSubtypeSet(count) { return buildS312HalfAngleKnownSet(count); }
  function buildS312RadicalHalfSimplifySubtypeSet(count) { return buildS312RadicalHalfSimplifySet(count); }
  function buildS312TanSubstitutionSubtypeSet(count) { return buildS312TanSubstitutionSet(count); }
  function buildS312QuadraticDoubleHalfSubtypeSet(count) { return buildS312QuadraticDoubleHalfSet(count); }
  function buildS312ProductValuesSubtypeSet(count) { return buildS312ProductValuesSet(count); }
