  function buildS312GridAngleSubtypeSet(count) { return buildS312GridAngleSet(count); }

  function s313Pick(items) {
    return items[randInt(0, items.length - 1)];
  }

  function s313Pi(num, den = 1) {
    const f = makeFraction(num, den);
    if (f.num === 0) return '0';
    const sign = f.num < 0 ? '-' : '';
    const absNum = Math.abs(f.num);
    if (f.den === 1) {
      if (absNum === 1) return `${sign}\\pi`;
      return `${sign}${absNum}\\pi`;
    }
    if (absNum === 1) return `${sign}\\frac{\\pi}{${f.den}}`;
    return `${sign}\\frac{${absNum}\\pi}{${f.den}}`;
  }

  function s313ShiftText(hNum, hDen = 1) {
    const h = makeFraction(hNum, hDen);
    if (h.num === 0) return 'x';
    const body = s313Pi(Math.abs(h.num), h.den);
    return h.num > 0 ? `x-${body}` : `x+${body}`;
  }

  function s313Arg(k, hNum = 0, hDen = 1) {
    const shift = s313ShiftText(hNum, hDen);
    if (hNum === 0) return k === 1 ? 'x' : `${k}x`;
    return k === 1 ? shift : `${k}(${shift})`;
  }

  function s313LinearArg(k, cNum = 0, cDen = 1) {
    const base = k === 1 ? 'x' : `${k}x`;
    const c = makeFraction(cNum, cDen);
    if (c.num === 0) return base;
    const sign = c.num > 0 ? '+' : '-';
    return `${base}${sign}${s313Pi(Math.abs(c.num), c.den)}`;
  }

  function s313SignedNumber(n) {
    if (n === 0) return '';
    return n > 0 ? `+${n}` : `${n}`;
  }

  function s313RangeText(a, d) {
    const low = d - Math.abs(a);
    const high = d + Math.abs(a);
    return `\\([${low},${high}]\\)`;
  }

  function s313FuncText(kind, a, arg, d = 0) {
    const coeff = a === 1 ? '' : a === -1 ? '-' : `${a}`;
    return `y=${coeff}\\${kind}(${arg})${s313SignedNumber(d)}`;
  }

  function buildS313PeriodAmplitudeSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const kind = s313Pick(['sin', 'cos', 'tan']);
      const k = s313Pick([2, 3, 4, 5, 6]);
      const a = kind === 'tan' ? s313Pick([1, -1, 2, -2]) : s313Pick([2, -2, 3, -3, 4, -4, 5]);
      const h = s313Pick([[0, 1], [1, 6], [1, 4], [1, 3], [-1, 6]]);
      const d = s313Pick([-3, -1, 0, 2, 4]);
      const period = kind === 'tan' ? s313Pi(1, k) : s313Pi(2, k);
      const f = s313FuncText(kind, a, s313Arg(k, h[0], h[1]), d);
      if (kind === 'tan') {
        questions.push(`求函數 \\(${f}\\) 的最小正週期。`);
        answers.push(`簡答：\\(${period}\\)。過程：正切函數 \\(\\tan x\\) 的基本週期為 \\(\\pi\\)，內部角為 \\(${k}\\) 倍，所以週期為 \\(\\frac{\\pi}{${k}}\\)。外部的係數與上下平移不改變週期。`);
      } else {
        questions.push(`求函數 \\(${f}\\) 的振幅與最小正週期。`);
        answers.push(`簡答：振幅 \\(${Math.abs(a)}\\)，週期 \\(${period}\\)。過程：\\(\\sin\\) 與 \\(\\cos\\) 的振幅為外部係數絕對值 \\(|${a}|=${Math.abs(a)}\\)，基本週期 \\(2\\pi\\) 被內部係數 ${k} 壓縮為 \\(\\frac{2\\pi}{${k}}\\)。`);
      }
    }
    return { questions, answers };
  }

  function buildS313TransformEquationSet(count) {
    const questions = [];
    const answers = [];
    const bases = ['sin', 'cos', 'tan'];
    for (let i = 0; i < count; i += 1) {
      const kind = s313Pick(bases);
      const k = s313Pick([1, 2, 3, 4]);
      const h = s313Pick([[1, 6], [1, 4], [1, 3], [-1, 4], [0, 1]]);
      const a = s313Pick([2, 3, -2, -3]);
      const d = s313Pick([-2, -1, 1, 3]);
      const f = s313FuncText(kind, a, s313Arg(k, h[0], h[1]), d);
      questions.push(`將 \\(y=\\${kind} x\\) 的圖形水平位移 \\(${s313Pi(h[0], h[1])}\\)，再將振幅或縱向伸縮倍數變為 \\(${a}\\)，最後上下平移 ${d} 單位，求新函數。`);
      answers.push(`簡答：\\(${f}\\)。過程：水平位移寫成 \\(x-h\\)，內部若再作 ${k} 倍水平壓縮則成 \\(${s313Arg(k, h[0], h[1])}\\)；外部乘上 ${a}，再加上 ${d}。`);
    }
    return { questions, answers };
  }

  function buildS313SymmetrySet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const kind = s313Pick(['sin', 'cos']);
      const k = s313Pick([1, 2, 3, 4]);
      const h = s313Pick([[0, 1], [1, 6], [1, 4], [1, 3]]);
      const d = s313Pick([-2, 0, 3]);
      const a = s313Pick([2, -3, 4]);
      const f = s313FuncText(kind, a, s313Arg(k, h[0], h[1]), d);
      if (kind === 'cos') {
        questions.push(`求函數 \\(${f}\\) 的一族對稱軸方程式。`);
        answers.push(`簡答：\\(x=${s313Pi(h[0], h[1])}+\\frac{n\\pi}{${k}}\\)，\\(n\\in\\mathbb Z\\)。過程：\\(\\cos\\) 的波峰、波谷都落在對稱軸上；令內部角為 \\(n\\pi\\)，解得 \\(x=h+\\frac{n\\pi}{${k}}\\)。`);
      } else {
        questions.push(`求函數 \\(${f}\\) 的一族對稱中心。`);
        answers.push(`簡答：\\((${s313Pi(h[0], h[1])}+\\frac{n\\pi}{${k}},${d})\\)，\\(n\\in\\mathbb Z\\)。過程：\\(\\sin\\) 圖形的平衡點是對稱中心；令內部角為 \\(n\\pi\\)，函數值回到中線 \\(y=${d}\\)。`);
      }
    }
    return { questions, answers };
  }

  function buildS313AbsolutePeriodSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const kind = s313Pick(['sin', 'cos']);
      const k = s313Pick([1, 2, 3, 4, 5]);
      const period = s313Pi(1, k);
      questions.push(`求函數 \\(y=|\\${kind} ${k === 1 ? 'x' : `${k}x`}|\\) 的最小正週期。`);
      answers.push(`簡答：\\(${period}\\)。過程：原本 \\(\\${kind}\\) 的週期為 \\(\\frac{2\\pi}{${k}}\\)，加絕對值後上下兩半波重合，週期減半為 \\(\\frac{\\pi}{${k}}\\)。`);
    }
    return { questions, answers };
  }

  function buildS313MonotonicIntervalSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const k = s313Pick([1, 2, 3, 4]);
      const sign = s313Pick([1, -1]);
      const end = s313Pi(1, k);
      const mid = s313Pi(1, 2 * k);
      const body = k === 1 ? 'x' : `${k}x`;
      if (sign > 0) {
        questions.push(`在區間 \\([0,${end}]\\) 內，寫出函數 \\(y=\\sin ${body}\\) 的遞增區間與遞減區間。`);
        answers.push(`簡答：遞增 \\([0,${mid}]\\)，遞減 \\([${mid},${end}]\\)。過程：令 \\(u=${body}\\)，當 \\(u\\) 從 0 到 \\(\\frac{\\pi}{2}\\) 時 \\(\\sin u\\) 遞增；從 \\(\\frac{\\pi}{2}\\) 到 \\(\\pi\\) 時遞減，再把 \\(u\\) 換回 \\(x\\)。`);
      } else {
        questions.push(`在區間 \\([0,${end}]\\) 內，寫出函數 \\(y=-\\sin ${body}\\) 的遞增區間與遞減區間。`);
        answers.push(`簡答：遞增 \\([${mid},${end}]\\)，遞減 \\([0,${mid}]\\)。過程：\\(-\\sin u\\) 會把 \\(\\sin u\\) 的增減方向上下翻轉；原本先增後減，因此翻轉後先減後增。`);
      }
    }
    return { questions, answers };
  }

  function buildS313ExtremaRangeSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const kind = s313Pick(['sin', 'cos']);
      const a = s313Pick([2, -2, 3, -4, 5]);
      const k = s313Pick([1, 2, 3, 4]);
      const d = s313Pick([-3, -1, 0, 2, 5]);
      const f = s313FuncText(kind, a, s313Arg(k), d);
      questions.push(`求函數 \\(${f}\\) 的最大值、最小值與值域。`);
      answers.push(`簡答：最大值 ${d + Math.abs(a)}，最小值 ${d - Math.abs(a)}，值域 ${s313RangeText(a, d)}。過程：\\(\\${kind}\\) 的值域為 \\([-1,1]\\)，乘上 ${a} 後上下幅度為 ${Math.abs(a)}，再平移到中線 \\(y=${d}\\)。`);
    }
    return { questions, answers };
  }

  function buildS313RestrictedRangeSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s313Pick([2, 3, -2, -3, 4]);
      const d = s313Pick([-2, 0, 1, 3]);
      const low = Math.min(d, d + a);
      const high = Math.max(d, d + a);
      questions.push(`在區間 \\([0,\\pi]\\) 內，求 \\(y=${a === 1 ? '' : a === -1 ? '-' : a}\\sin x${s313SignedNumber(d)}\\) 的值域。`);
      answers.push(`簡答：\\([${low},${high}]\\)。過程：在 \\([0,\\pi]\\) 內，\\(\\sin x\\) 的值域為 \\([0,1]\\)。代入 \\(y=${a}\\sin x${s313SignedNumber(d)}\\)，端點與最高點給出值域。`);
    }
    return { questions, answers };
  }

  function buildS313RootCountSet(count) {
    const questions = [];
    const answers = [];
    const constants = [
      { text: '0', per: 2 },
      { text: '\\frac12', per: 2 },
      { text: '-\\frac12', per: 2 },
      { text: '1', per: 1 },
      { text: '-1', per: 1 },
    ];
    for (let i = 0; i < count; i += 1) {
      const k = s313Pick([1, 2, 3, 4]);
      const c = s313Pick(constants);
      const total = c.per * k;
      questions.push(`在區間 \\([0,2\\pi)\\) 內，判定方程式 \\(\\sin ${k === 1 ? 'x' : `${k}x`}=${c.text}\\) 有幾個實根。`);
      answers.push(`簡答：${total} 個。過程：\\(\\sin u=${c.text}\\) 在一個週期 \\([0,2\\pi)\\) 內有 ${c.per} 個解；\\(u=${k === 1 ? 'x' : `${k}x`}\\) 讓 \\([0,2\\pi)\\) 內包含 ${k} 個完整週期，所以共有 ${total} 個。`);
    }
    return { questions, answers };
  }

  function buildS313EquationCountSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 2;
      const k = s313Pick([1, 2, 3, 4]);
      if (mode === 0) {
        questions.push(`在區間 \\([0,2\\pi)\\) 內，方程式 \\(|\\cos ${k === 1 ? 'x' : `${k}x`}|=\\frac12\\) 有幾個解？`);
        answers.push(`簡答：${4 * k} 個。過程：\\(|\\cos u|=\\frac12\\) 在一個週期內有 4 個解，\\(u=${k === 1 ? 'x' : `${k}x`}\\) 造成 ${k} 個完整週期。`);
      } else {
        const m = s313Pick([-2, -1, 1, 2, 3]);
        questions.push(`在區間 \\([0,2\\pi)\\) 內，方程式 \\(\\tan ${k === 1 ? 'x' : `${k}x`}=${m}\\) 有幾個解？`);
        answers.push(`簡答：${2 * k} 個。過程：\\(\\tan u=${m}\\) 每個長度 \\(\\pi\\) 的週期有 1 個解；\\(u=${k === 1 ? 'x' : `${k}x`}\\) 在 \\([0,2\\pi)\\) 內走過 ${2 * k} 個正切週期。`);
      }
    }
    return { questions, answers };
  }

  function buildS313ExactComparisonSet(count) {
    const questions = [];
    const answers = [];
    const angles = [
      { a: '\\frac{\\pi}{6}', s: '\\frac12', c: '\\frac{\\sqrt3}{2}', type: 'half' },
      { a: '\\frac{\\pi}{4}', s: '\\frac{\\sqrt2}{2}', c: '\\frac{\\sqrt2}{2}', type: 'sqrt2' },
      { a: '\\frac{\\pi}{3}', s: '\\frac{\\sqrt3}{2}', c: '\\frac12', type: 'sqrt3' },
    ];
    function specialValue(k, type) {
      if (type === 'half') return fractionToLatex(makeFraction(k + 2, 2));
      if (type === 'sqrt2') {
        if (k === 1) return `1+\\frac{\\sqrt2}{2}`;
        if (k === 2) return `1+\\sqrt2`;
        return `1+\\frac{${k}\\sqrt2}{2}`;
      }
      if (k === 1) return `1+\\frac{\\sqrt3}{2}`;
      if (k === 2) return `1+\\sqrt3`;
      return `1+\\frac{${k}\\sqrt3}{2}`;
    }
    for (let i = 0; i < count; i += 1) {
      const item = s313Pick(angles);
      const k = s313Pick([1, 2, 3]);
      const value = specialValue(k, item.type);
      const coeff = k === 1 ? '' : `${k}`;
      const mult = k === 1 ? item.s : `${k}\\cdot ${item.s}`;
      questions.push(`設 \\(f(x)=${coeff}\\sin x+1\\)，求 \\(f(${item.a})\\)，並判斷 \\(\\sin ${item.a}\\) 與 \\(\\cos ${item.a}\\) 的大小。`);
      answers.push(`簡答：\\(f(${item.a})=${value}\\)。過程：直接代入特殊角；\\(${item.a}\\) 的正弦值為 \\(${item.s}\\)，餘弦值為 \\(${item.c}\\)，所以 \\(f(${item.a})=${mult}+1=${value}\\)，再比較正弦與餘弦的大小。`);
    }
    return { questions, answers };
  }

  function buildS313GraphParameterSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s313Pick([2, 3, 4, 5]);
      const d = s313Pick([-2, 0, 3]);
      const k = s313Pick([1, 2, 3, 4]);
      const max = d + a;
      const min = d - a;
      const period = s313Pi(2, k);
      questions.push(`某正弦函數可寫成 \\(y=a\\sin bx+d\\)，其最大值為 ${max}、最小值為 ${min}、最小正週期為 \\(${period}\\)。求 \\(a,d,b\\) 的一組可能值。`);
      answers.push(`簡答：\\(a=${a},d=${d},b=${k}\\)。過程：振幅 \\(a=\\frac{${max}-(${min})}{2}=${a}\\)，中線 \\(d=\\frac{${max}+(${min})}{2}=${d}\\)；週期 \\(\\frac{2\\pi}{b}=${period}\\)，所以 \\(b=${k}\\)。`);
    }
    return { questions, answers };
  }

  function buildS313PeakValleySet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s313Pick([2, 3, 4]);
      const d = s313Pick([-1, 0, 2]);
      const k = s313Pick([1, 2, 3]);
      const peakX = s313Pi(1, 2 * k);
      const valleyX = s313Pi(3, 2 * k);
      questions.push(`一個函數形如 \\(y=a\\sin bx+d\\)，已知波峰在 \\((${peakX},${d + a})\\)，相鄰波谷在 \\((${valleyX},${d - a})\\)。求此函數。`);
      answers.push(`簡答：\\(y=${a}\\sin ${k === 1 ? 'x' : `${k}x`}${s313SignedNumber(d)}\\)。過程：波峰與波谷的中線為 \\(y=${d}\\)，振幅為 ${a}；\\(\\sin bx\\) 的第一個波峰在 \\(x=\\frac{\\pi}{2b}\\)，由 \\(${peakX}\\) 得 \\(b=${k}\\)。`);
    }
    return { questions, answers };
  }

  function buildS313FerrisModelSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const r = s313Pick([10, 15, 20, 30]);
      const low = s313Pick([2, 5, 8]);
      const minutes = s313Pick([4, 5, 6, 10]);
      const center = low + r;
      questions.push(`摩天輪半徑 ${r} 公尺，最低點離地 ${low} 公尺，轉一圈 ${minutes} 分鐘。若乘客從最低點開始，寫出高度 \\(h(t)\\) 與時間 \\(t\\)（分鐘）的函數式。`);
      answers.push(`簡答：\\(h(t)=${center}-${r}\\cos\\frac{2\\pi t}{${minutes}}\\)。過程：中線高度為 ${center}，振幅為 ${r}，角速度為 \\(\\frac{2\\pi}{${minutes}}\\)。從最低點開始，所以用 \\(-\\cos\\) 表示。`);
    }
    return { questions, answers };
  }

  function buildS313ClockPendulumSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const len = s313Pick([6, 8, 10, 12]);
      const minutes = s313Pick([10, 15, 20, 30]);
      const theta = s313Pi(minutes, 30);
      const area = simplifyFraction(len * len * minutes, 60);
      questions.push(`分針長 ${len} 公分，從某時刻開始經過 ${minutes} 分鐘，求分針掃過的扇形面積。`);
      answers.push(`簡答：\\(${fractionToLatex(area)}\\pi\\) 平方公分。過程：${minutes} 分鐘對應圓心角 \\(${theta}\\) 弧度，扇形面積為 \\(\\frac12 r^2\\theta=\\frac12\\cdot${len}^2\\cdot ${theta}\\)。`);
    }
    return { questions, answers };
  }

  function buildS313ReverseTransformSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const kind = s313Pick(['sin', 'cos']);
      const a = s313Pick([2, 3, 4]);
      const k = s313Pick([2, 3, 4]);
      const h = s313Pick([[1, 6], [1, 4], [1, 3]]);
      const d = s313Pick([-2, 1, 3]);
      const f = s313FuncText(kind, a, s313Arg(k, h[0], h[1]), d);
      questions.push(`函數 \\(y=\\${kind} x\\) 經過水平壓縮、平移與縱向變換後得到 \\(${f}\\)。說明其變換步驟。`);
      answers.push(`簡答：水平壓縮為原來的 \\(\\frac1{${k}}\\) 倍，向右平移 \\(${s313Pi(h[0], h[1])}\\)，縱向伸縮 ${a} 倍，並上下平移 ${d} 單位。過程：由內部 \\(${s313Arg(k, h[0], h[1])}\\) 讀出水平變換，由外部係數 ${a} 與常數 ${d} 讀出縱向變換。`);
    }
    return { questions, answers };
  }

  function buildS313PeriodTransformFiveSubtypeMixedSet(count) {
    return buildS223MixedSet([
      buildS313PeriodAmplitudeSet,
      buildS313TransformEquationSet,
      buildS313SymmetrySet,
      buildS313AbsolutePeriodSet,
      buildS313MonotonicIntervalSet,
    ], count);
  }

  function buildS313RangeEquationFiveSubtypeMixedSet(count) {
    return buildS223MixedSet([
      buildS313ExtremaRangeSet,
      buildS313RestrictedRangeSet,
      buildS313RootCountSet,
      buildS313EquationCountSet,
      buildS313ExactComparisonSet,
    ], count);
  }

  function buildS313ParameterModelFiveSubtypeMixedSet(count) {
    return buildS223MixedSet([
      buildS313GraphParameterSet,
      buildS313PeakValleySet,
      buildS313FerrisModelSet,
      buildS313ClockPendulumSet,
      buildS313ReverseTransformSet,
    ], count);
  }

  function buildS313PeriodAmplitudeSubtypeSet(count) { return buildS313PeriodAmplitudeSet(count); }
  function buildS313TransformEquationSubtypeSet(count) { return buildS313TransformEquationSet(count); }
  function buildS313SymmetrySubtypeSet(count) { return buildS313SymmetrySet(count); }
  function buildS313AbsolutePeriodSubtypeSet(count) { return buildS313AbsolutePeriodSet(count); }
  function buildS313MonotonicIntervalSubtypeSet(count) { return buildS313MonotonicIntervalSet(count); }
  function buildS313ExtremaRangeSubtypeSet(count) { return buildS313ExtremaRangeSet(count); }
  function buildS313RestrictedRangeSubtypeSet(count) { return buildS313RestrictedRangeSet(count); }
  function buildS313RootCountSubtypeSet(count) { return buildS313RootCountSet(count); }
  function buildS313EquationCountSubtypeSet(count) { return buildS313EquationCountSet(count); }
  function buildS313ExactComparisonSubtypeSet(count) { return buildS313ExactComparisonSet(count); }
  function buildS313GraphParameterSubtypeSet(count) { return buildS313GraphParameterSet(count); }
  function buildS313PeakValleySubtypeSet(count) { return buildS313PeakValleySet(count); }
  function buildS313FerrisModelSubtypeSet(count) { return buildS313FerrisModelSet(count); }
  function buildS313ClockPendulumSubtypeSet(count) { return buildS313ClockPendulumSet(count); }
  function buildS313ReverseTransformSubtypeSet(count) { return buildS313ReverseTransformSet(count); }

  function s314TrigTerm(coeff, trig, first = false) {
    if (coeff === 0) return '';
    const sign = coeff < 0 ? '-' : first ? '' : '+';
    const abs = Math.abs(coeff);
    const body = abs === 1 ? `\\${trig} x` : `${abs}\\${trig} x`;
    return `${sign}${body}`;
  }

  function s314CoeffBody(coeff, body, first = false) {
    if (coeff === 0) return '';
    const sign = coeff < 0 ? '-' : first ? '' : '+';
    const abs = Math.abs(coeff);
    return `${sign}${abs === 1 ? body : `${abs}${body}`}`;
  }

  function s314ComboText(a, b, c = 0) {
    const first = s314TrigTerm(a, 'sin', true);
    const second = s314TrigTerm(b, 'cos', !first);
    const base = `${first}${second}` || '0';
    return `${base}${s313SignedNumber(c)}`;
  }

  function s314Triple() {
    return s313Pick([
      [3, 4, 5],
      [5, 12, 13],
      [8, 15, 17],
      [7, 24, 25],
    ]);
  }

  function s314MaxMinText(maxValue, minValue) {
    return `最大值 ${maxValue}，最小值 ${minValue}`;
  }

  function s314Root2LinearText(integerPart, rootCoeff) {
    const terms = [];
    if (integerPart !== 0) terms.push(`${integerPart}`);
    if (rootCoeff !== 0) {
      const abs = Math.abs(rootCoeff);
      const rootTerm = abs === 1 ? '\\sqrt2' : `${abs}\\sqrt2`;
      if (terms.length === 0) {
        terms.push(rootCoeff < 0 ? `-${rootTerm}` : rootTerm);
      } else {
        terms.push(`${rootCoeff < 0 ? '-' : '+'}${rootTerm}`);
      }
    }
    return terms.join('') || '0';
  }

  function s314ValueText(numerator, denominator = 1) {
    const value = simplifyFraction(numerator, denominator);
    if (value.den === 1) return `${value.num}`;
    const sign = value.num < 0 ? '-' : '';
    return `${sign}\\frac{${Math.abs(value.num)}}{${value.den}}`;
  }

  function s314TrigArgument(variable, multiple) {
    return multiple === 1 ? variable : `${multiple}${variable}`;
  }

  function s314CoeffParen(coeff, body) {
    if (coeff === 1) return body;
    if (coeff === -1) return `-${body}`;
    return `${coeff}${body}`;
  }

  function buildS314BasicComboExtremaSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const [p, q, r] = s314Triple();
      const signA = s313Pick([1, -1]);
      const signB = s313Pick([1, -1]);
      const a = signA * p;
      const b = signB * q;
      const c = s313Pick([-5, -2, 0, 3, 7]);
      questions.push(`求函數 \\(y=${s314ComboText(a, b, c)}\\) 的最大值與最小值。`);
      answers.push(`簡答：${s314MaxMinText(c + r, c - r)}。過程：把 \\(${s314ComboText(a, b)}\\) 疊合成 \\(${r}\\sin(x+\\theta)\\)，其中 \\(\\cos\\theta=${formatFraction(a, r)}\\)、\\(\\sin\\theta=${formatFraction(b, r)}\\)。因此原函數值域為 \\([${c - r},${c + r}]\\)。`);
    }
    return { questions, answers };
  }

  function buildS314RestrictedRangeSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s313Pick([1, 2, 3, 4]);
      const c = s313Pick([-3, 0, 2]);
      const mode = i % 2;
      if (mode === 0) {
        questions.push(`在 \\(0\\le x\\le \\frac{\\pi}{2}\\) 範圍內，求 \\(y=${a}(\\sin x+\\cos x)${s313SignedNumber(c)}\\) 的最大值與最小值。`);
        answers.push(`簡答：最大值 \\(${s314Root2LinearText(c, a)}\\)，最小值 ${c + a}。過程：\\(\\sin x+\\cos x=\\sqrt2\\sin(x+\\frac\\pi4)\\)。在此區間內，\\(\\sin x+\\cos x\\) 的最大值為 \\(\\sqrt2\\)，兩端點的值都為 1，所以代回即可。`);
      } else {
        questions.push(`在 \\(-\\frac{\\pi}{4}\\le x\\le \\frac{\\pi}{4}\\) 範圍內，求 \\(y=${a}(\\sin x+\\cos x)${s313SignedNumber(c)}\\) 的值域。`);
        answers.push(`簡答：\\([${c},${s314Root2LinearText(c, a)}]\\)。過程：令 \\(t=x+\\frac\\pi4\\)，則 \\(t\\in[0,\\frac\\pi2]\\)，\\(\\sin x+\\cos x=\\sqrt2\\sin t\\)，所以範圍從 0 到 \\(\\sqrt2\\)。`);
      }
    }
    return { questions, answers };
  }

  function buildS314QuadraticReductionSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const [p, q, r] = s314Triple();
      const base = s313Pick([1, 3, 5]);
      const a = base;
      const c = base + 2 * p;
      const b = 2 * q;
      const mid = base + p;
      const expr = `${s314CoeffBody(a, '\\sin^2x', true)}${s314CoeffBody(b, '\\sin x\\cos x')}${s314CoeffBody(c, '\\cos^2x')}`;
      questions.push(`求 \\(y=${expr}\\) 的最大值與最小值。`);
      answers.push(`簡答：最大值 ${mid + r}，最小值 ${mid - r}。過程：用 \\(\\sin^2x=\\frac{1-\\cos2x}{2}\\)、\\(\\cos^2x=\\frac{1+\\cos2x}{2}\\)、\\(\\sin x\\cos x=\\frac12\\sin2x\\)，可化為 \\(${mid}+${p}\\cos2x+${q}\\sin2x\\)，振幅為 \\(\\sqrt{${p}^2+${q}^2}=${r}\\)。`);
    }
    return { questions, answers };
  }

  function buildS314SubstitutionSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const m = s313Pick([1, 2]);
      const n = s313Pick([1, 2]);
      const linearPart = s314CoeffParen(m, '(\\sin x+\\cos x)');
      const tLinearPart = s314CoeffBody(m, 't');
      questions.push(`令 \\(t=\\sin x+\\cos x\\)，求函數 \\(y=(\\sin x+\\cos x)^2+${linearPart}+${n}\\) 的最小值。`);
      answers.push(`簡答：\\(${s314ValueText(4 * n - m * m, 4)}\\)。過程：令 \\(t=\\sin x+\\cos x\\)，則 \\(t\\in[-\\sqrt2,\\sqrt2]\\)，原式成 \\(t^2${tLinearPart}+${n}\\)。頂點 \\(t=-\\frac{${m}}{2}\\) 落在範圍內，所以最小值為 \\(${n}-\\frac{${m * m}}{4}=${s314ValueText(4 * n - m * m, 4)}\\)。`);
    }
    return { questions, answers };
  }

  function buildS314FractionalExtremaSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s313Pick([1, 2, 3]);
      const b = s313Pick([1, 2]);
      const c = s313Pick([3, 4, 5]);
      const d = s313Pick([1, 2]);
      const f1 = simplifyFraction(a - b, c - d);
      const f2 = simplifyFraction(a + b, c + d);
      const values = [f1, f2].sort((x, y) => x.num / x.den - y.num / y.den);
      const numerator = `${a}${s314CoeffBody(b, '\\sin x')}`;
      const denominator = `${c}${s314CoeffBody(d, '\\sin x')}`;
      const numeratorU = `${a}${s314CoeffBody(b, 'u')}`;
      const denominatorU = `${c}${s314CoeffBody(d, 'u')}`;
      questions.push(`求函數 \\(f(x)=\\frac{${numerator}}{${denominator}}\\) 的最大值與最小值。`);
      answers.push(`簡答：最大值 \\(${s314ValueText(values[1].num, values[1].den)}\\)，最小值 \\(${s314ValueText(values[0].num, values[0].den)}\\)。過程：令 \\(u=\\sin x\\)，\\(-1\\le u\\le1\\)，且分母 \\(${denominatorU}\\) 恆為正。分式 \\(\\frac{${numeratorU}}{${denominatorU}}\\) 在此區間單調，因此只需比較 \\(u=-1,1\\) 的值。`);
    }
    return { questions, answers };
  }

  function buildS314ParameterInverseSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const [a0, b0, r] = s314Triple();
      const k = s313Pick([1, 2, 3, 4]);
      const d = s313Pick([-3, 0, 5]);
      const max = d + r;
      const min = d - r;
      const period = s313Pi(2, k);
      questions.push(`設 \\(f(x)=a\\sin kx+b\\cos kx+c\\)，已知週期為 \\(${period}\\)、最大值為 ${max}、最小值為 ${min}，且 \\(a=${a0}\\)、\\(b>0\\)。求 \\(b,c\\) 與 \\(k\\)。`);
      answers.push(`簡答：\\(b=${b0},c=${d},k=${k}\\)。過程：最大最小值給出振幅 \\(R=\\frac{${max}-(${min})}{2}=${r}\\)，中線 \\(c=\\frac{${max}+(${min})}{2}=${d}\\)。又 \\(R^2=a^2+b^2\\)，所以 \\(b=\\sqrt{${r}^2-${a0}^2}=${b0}\\)。週期 \\(\\frac{2\\pi}{k}=${period}\\)，因此 \\(k=${k}\\)。`);
    }
    return { questions, answers };
  }

  function buildS314EquationSolvingSet(count) {
    const questions = [];
    const answers = [];
    const cases = [
      { expr: '\\sin x+\\cos x=1', ans: '0,\\frac{\\pi}{2}' },
      { expr: '\\sin x-\\cos x=1', ans: '\\frac{\\pi}{2},\\pi' },
      { expr: '\\sin x+\\cos x=-1', ans: '\\pi,\\frac{3\\pi}{2}' },
      { expr: '\\sin x-\\cos x=-1', ans: '0,\\frac{3\\pi}{2}' },
    ];
    for (let i = 0; i < count; i += 1) {
      const item = s313Pick(cases);
      questions.push(`解方程式 \\(${item.expr}\\)，求 \\(0\\le x<2\\pi\\) 內的所有解。`);
      answers.push(`簡答：\\(x=${item.ans}\\)。過程：把左式疊合成 \\(\\sqrt2\\sin(x\\pm\\frac\\pi4)\\)，再解特殊角；也可直接檢查單位圓上 \\(\\sin x\\) 與 \\(\\cos x\\) 的組合。`);
    }
    return { questions, answers };
  }

  function buildS314CombineFormSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const [p, q, r] = s314Triple();
      const mode = i % 2;
      if (mode === 0) {
        questions.push(`將 \\(${p}\\sin x+${q}\\cos x\\) 化為 \\(R\\sin(x+\\theta)\\) 的形式，求 \\(R\\)、\\(\\cos\\theta\\)、\\(\\sin\\theta\\)。`);
        answers.push(`簡答：\\(R=${r},\\cos\\theta=${formatFraction(p, r)},\\sin\\theta=${formatFraction(q, r)}\\)。過程：展開 \\(R\\sin(x+\\theta)=R\\cos\\theta\\sin x+R\\sin\\theta\\cos x\\)，比較係數。`);
      } else {
        questions.push(`將 \\(${p}\\sin x-${q}\\cos x\\) 化為 \\(R\\sin(x-\\phi)\\) 的形式，求 \\(R\\)、\\(\\cos\\phi\\)、\\(\\sin\\phi\\)。`);
        answers.push(`簡答：\\(R=${r},\\cos\\phi=${formatFraction(p, r)},\\sin\\phi=${formatFraction(q, r)}\\)。過程：展開 \\(R\\sin(x-\\phi)=R\\cos\\phi\\sin x-R\\sin\\phi\\cos x\\)，再比較 \\(\\sin x\\)、\\(\\cos x\\) 的係數。`);
      }
    }
    return { questions, answers };
  }

  function buildS314GeometryModelSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const r = s313Pick([2, 3, 4, 5, 6]);
      questions.push(`在半徑為 ${r} 的半圓內接一個矩形，設矩形右上角與圓心連線和水平軸夾角為 \\(\\theta\\)。求矩形面積的最大值。`);
      answers.push(`簡答：${r * r}。過程：矩形寬為 \\(${2 * r}\\cos\\theta\\)，高為 \\(${r}\\sin\\theta\\)，面積 \\(A=${2 * r * r}\\sin\\theta\\cos\\theta=${r * r}\\sin2\\theta\\)，最大值為 ${r * r}。`);
    }
    return { questions, answers };
  }

  function buildS314WaveModelSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const [a, b, r] = s314Triple();
      const w = s313Pick([1, 2, 3, 4]);
      questions.push(`兩個同頻波疊合後位移為 \\(y=${a}\\sin ${s314TrigArgument('t', w)}+${b}\\cos ${s314TrigArgument('t', w)}\\)。求合成波的最大位移。`);
      answers.push(`簡答：${r}。過程：同頻的 \\(a\\sin\\omega t+b\\cos\\omega t\\) 可疊合成 \\(R\\sin(\\omega t+\\theta)\\)，其中 \\(R=\\sqrt{${a}^2+${b}^2}=${r}\\)，所以最大位移為 ${r}。`);
    }
    return { questions, answers };
  }

  function buildS314ComboExtremaFiveSubtypeMixedSet(count) {
    return buildS223MixedSet([
      buildS314BasicComboExtremaSet,
      buildS314RestrictedRangeSet,
      buildS314QuadraticReductionSet,
      buildS314SubstitutionSet,
      buildS314FractionalExtremaSet,
    ], count);
  }

  function buildS314InverseModelFiveSubtypeMixedSet(count) {
    return buildS223MixedSet([
      buildS314ParameterInverseSet,
      buildS314EquationSolvingSet,
      buildS314CombineFormSet,
      buildS314GeometryModelSet,
      buildS314WaveModelSet,
    ], count);
  }

  function buildS314BasicComboExtremaSubtypeSet(count) { return buildS314BasicComboExtremaSet(count); }
  function buildS314RestrictedRangeSubtypeSet(count) { return buildS314RestrictedRangeSet(count); }
  function buildS314QuadraticReductionSubtypeSet(count) { return buildS314QuadraticReductionSet(count); }
  function buildS314SubstitutionSubtypeSet(count) { return buildS314SubstitutionSet(count); }
  function buildS314FractionalExtremaSubtypeSet(count) { return buildS314FractionalExtremaSet(count); }
  function buildS314ParameterInverseSubtypeSet(count) { return buildS314ParameterInverseSet(count); }
  function buildS314EquationSolvingSubtypeSet(count) { return buildS314EquationSolvingSet(count); }
  function buildS314CombineFormSubtypeSet(count) { return buildS314CombineFormSet(count); }
  function buildS314GeometryModelSubtypeSet(count) { return buildS314GeometryModelSet(count); }
  function buildS314WaveModelSubtypeSet(count) { return buildS314WaveModelSet(count); }

  function s321Pow(base, exponent) {
    return `${base}^{${exponent}}`;
  }

  function s321Signed(value) {
    return value < 0 ? `${value}` : `${value}`;
  }

  function s321Plus(value) {
    if (value === 0) return '';
    return value > 0 ? `+${value}` : `${value}`;
  }

  function s321Term(coeff, body, first = false) {
    if (coeff === 0) return '';
    const sign = coeff < 0 ? '-' : first ? '' : '+';
    const abs = Math.abs(coeff);
    return `${sign}${abs === 1 ? body : `${abs}${body}`}`;
  }

  function s321BaseText(base) {
    return base.den ? `\\frac{${base.num}}{${base.den}}` : `${base}`;
  }

  function s321Fraction(num, den) {
    const frac = simplifyFraction(num, den);
    return frac.den === 1 ? `${frac.num}` : `\\frac{${frac.num}}{${frac.den}}`;
  }

  function s321PowerValue(base, exponent) {
    return Math.pow(base, exponent);
  }

  function s321IntervalFromRoots(a, b, relation) {
    const left = Math.min(a, b);
    const right = Math.max(a, b);
    if (relation === '<') return `\\(${left}<x<${right}\\)`;
    if (relation === '\\le') return `\\(${left}\\le x\\le ${right}\\)`;
    if (relation === '>') return `\\(x<${left}\\) 或 \\(x>${right}\\)`;
    return `\\(x\\le ${left}\\) 或 \\(x\\ge ${right}\\)`;
  }

  function s321Pick(items) {
    return items[randInt(0, items.length - 1)];
  }

  function buildS321ExponentLawSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const b = s321Pick([2, 3, 5]);
        const m = s321Pick([2, 3, 4]);
        const n = s321Pick([2, 3]);
        const value = Math.pow(b, m * n);
        questions.push(`計算 \\((${b}^{${m}})^{${n}}\\) 的值。`);
        answers.push(`簡答：${value}。過程：乘方的乘方，指數相乘，\\((${b}^{${m}})^{${n}}=${b}^{${m * n}}=${value}\\)。`);
        continue;
      }
      if (mode === 1) {
        const b = s321Pick([2, 3, 5]);
        const p = s321Pick([2, 3]);
        const q = s321Pick([2, 3, 4]);
        const value = Math.pow(b, q - p);
        questions.push(`化簡 \\(\\left(\\frac{1}{${b}}\\right)^{-${q}}\\div ${b}^{${p}}\\)。`);
        answers.push(`簡答：${value}。過程：\\((\\frac1{${b}})^{-${q}}=${b}^{${q}}\\)，再同底數相除，得 \\(${b}^{${q}-${p}}=${b}^{${q - p}}=${value}\\)。`);
        continue;
      }
      if (mode === 2) {
        const b = s321Pick([2, 3, 5]);
        const m = s321Pick([2, 3, 4]);
        const value = b ** 2;
        questions.push(`求 \\((${b ** m})^{${formatFraction(1, m)}}\\cdot ${b}^{-1}\\cdot ${b}^2\\) 的精確值。`);
        answers.push(`簡答：${value}。過程：\\((${b ** m})^{${formatFraction(1, m)}}=${b}\\)，原式為 \\(${b}\\cdot${b}^{-1}\\cdot${b}^2=${b}^{1-1+2}=${b}^2=${value}\\)。`);
        continue;
      }
      if (mode === 3) {
        const n = s321Pick([2, 3, 4]);
        const numerator = Math.pow(5, n) + Math.pow(5, -n);
        questions.push(`已知 \\(a^{x}+a^{-x}=5\\)，求 \\(a^{${n}x}+a^{-${n}x}\\) 可用遞推或平方關係表示的值。`);
        const value = n === 2 ? 23 : n === 3 ? 110 : 527;
        answers.push(`簡答：${value}。過程：令 \\(t=a^x+a^{-x}=5\\)。利用 \\(a^{2x}+a^{-2x}=t^2-2\\)，逐次遞推即可；本題代入後得到 ${value}。`);
        continue;
      }
      const n = s321Pick([2, 3, 4, 5]);
      questions.push(`化簡 \\((a^{1/${n}}-b^{1/${n}})(a^{1/${n}}+b^{1/${n}})\\)。`);
      answers.push(`簡答：\\(a^{${formatFraction(2, n)}}-b^{${formatFraction(2, n)}}\\)。過程：套用平方差，\\(X=a^{1/${n}},Y=b^{1/${n}}\\)，則 \\((X-Y)(X+Y)=X^2-Y^2\\)。`);
    }
    return { questions, answers };
  }

  function buildS321SizeComparisonSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const a = s321Pick([2, 3, 5]);
        const p = s321Pick([2, 3, 4]);
        const q = p + s321Pick([1, 2]);
        questions.push(`比較 \\(\\sqrt[${p}]{${a}}\\) 與 \\(\\sqrt[${q}]{${a}}\\) 的大小。`);
        answers.push(`簡答：\\(\\sqrt[${p}]{${a}}>\\sqrt[${q}]{${a}}\\)。過程：因為 ${a}>1，指數函數遞增，且 \\(\\frac1{${p}}>\\frac1{${q}}\\)，所以前者較大。`);
        continue;
      }
      if (mode === 1) {
        const p = s321Pick([2, 3, 4]);
        const q = p + 1;
        questions.push(`比較 \\((\\frac12)^{${p}}\\) 與 \\((\\frac12)^{${q}}\\) 的大小。`);
        answers.push(`簡答：\\((\\frac12)^{${p}}>(\\frac12)^{${q}}\\)。過程：底數 \\(\\frac12\\) 介於 0 與 1，指數愈大值愈小；因為 ${p}<${q}，所以前者較大。`);
        continue;
      }
      if (mode === 2) {
        const p = s321Pick([2, 3, 4]);
        questions.push(`若 \\(0<a<1\\)，比較 \\(a^2,a^3,a^{${formatFraction(1, p)}}\\) 的大小。`);
        answers.push(`簡答：\\(a^{${formatFraction(1, p)}}>a^2>a^3\\)。過程：當 \\(0<a<1\\) 時，指數愈大，值愈小；因為 \\(\\frac1{${p}}<2<3\\)，所以大小如上。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`比較 \\((\\sqrt2)^3\\) 與 \\((\\sqrt3)^2\\) 的大小。`);
        answers.push(`簡答：\\((\\sqrt2)^3< (\\sqrt3)^2\\)。過程：前者為 \\(2\\sqrt2\\)，平方後為 8；後者為 3，平方後為 9，兩者皆正，所以後者較大。`);
        continue;
      }
      const a = s321Pick([2, 3, 5]);
      questions.push(`比較 \\(a^{${formatFraction(1, 2)}}\\)、\\(a^{${formatFraction(2, 3)}}\\)、\\(a^{-1}\\) 的大小，其中 \\(a=${a}\\)。`);
      answers.push(`簡答：\\(a^{${formatFraction(2, 3)}}>a^{${formatFraction(1, 2)}}>a^{-1}\\)。過程：因為底數 ${a}>1，指數愈大值愈大，直接比較 \\(\\frac23,\\frac12,-1\\)。`);
    }
    return { questions, answers };
  }

  function buildS321EquationSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const a = s321Pick([2, 3, 4, 5]);
        const m = s321Pick([2, 3, 4]);
        const sol = s321Pick([-2, -1, 1, 2, 3]);
        const c = m * sol - 1;
        questions.push(`解方程式 \\(${a}^{${m}x-1}=${a}^{${c}}\\)。`);
        answers.push(`簡答：\\(x=${sol}\\)。過程：同底數且底數不為 1，可比較指數，得 \\(${m}x-1=${c}\\)，所以 \\(x=${sol}\\)。`);
        continue;
      }
      if (mode === 1) {
        const r = s321Pick([2, 3, 4]);
        const s = r + 1;
        const sum = r + s;
        const prod = r * s;
        questions.push(`解方程式 \\(4^x-${sum}\\cdot2^x+${prod}=0\\)。`);
        answers.push(`簡答：\\(x=\\log_2 ${r}\\) 或 \\(x=\\log_2 ${s}\\)。過程：令 \\(t=2^x>0\\)，得 \\(t^2-${sum}t+${prod}=0=(t-${r})(t-${s})\\)，所以 \\(2^x=${r}\\) 或 \\(2^x=${s}\\)。`);
        continue;
      }
      if (mode === 2) {
        const n = s321Pick([1, 2, 3]);
        questions.push(`解方程式 \\(25^x-2\\cdot5^{x-${n}}+5^{-${2 * n}}=0\\)。`);
        answers.push(`簡答：\\(x=-${n}\\)。過程：令 \\(t=5^x>0\\)，原式為 \\(t^2-2\\cdot5^{-${n}}t+5^{-${2 * n}}=0=(t-5^{-${n}})^2\\)，所以 \\(5^x=5^{-${n}}\\)，得 \\(x=-${n}\\)。`);
        continue;
      }
      if (mode === 3) {
        const a = s321Pick([2, 3, 4]);
        const b = a + 1;
        questions.push(`解聯立方程 \\(2^x+3^y=${a + b}\\)、\\(2^x\\cdot3^y=${a * b}\\)。`);
        answers.push(`簡答：\\((2^x,3^y)=(${a},${b})\\) 或 \\((${b},${a})\\)，再分別取對數。過程：令 \\(u=2^x,v=3^y\\)，則 \\(u+v=${a + b}\\)、\\(uv=${a * b}\\)，所以 \\(u,v\\) 是方程 \\(t^2-${a + b}t+${a * b}=0\\) 的兩根。`);
        continue;
      }
      const m = s321Pick([2, 4]);
      const sumText = s321Fraction(m * m + 1, m);
      const rhsText = s321Fraction(3 * (m * m + 1) - 2 * m, m);
      questions.push(`解方程式 \\(3(2^x+2^{-x})-2=${rhsText}\\)。`);
      answers.push(`簡答：\\(x=\\log_2 ${m}\\) 或 \\(x=-\\log_2 ${m}\\)。過程：令 \\(t=2^x>0\\)，得 \\(t+\\frac1t=${sumText}\\)，所以 \\(t=${m}\\) 或 \\(t=\\frac1{${m}}\\)。`);
    }
    return { questions, answers };
  }

  function buildS321InequalitySet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const left = s321Pick([-3, -2, -1]);
        const right = s321Pick([2, 3, 4]);
        const sum = left + right;
        const prod = left * right;
        const mid = sum === 0 ? 'x^2' : `x^2${s321Plus(-sum)}x`;
        questions.push(`解不等式 \\((\\frac12)^{${mid}${s321Plus(prod)}}>1\\)。`);
        answers.push(`簡答：${s321IntervalFromRoots(left, right, '<')}。過程：\\(1=(\\frac12)^0\\)，底數 \\(\\frac12<1\\)，所以指數需小於 0；此二次式的兩根為 ${left}、${right}，開口向上，小於 0 時落在兩根之間。`);
        continue;
      }
      if (mode === 1) {
        const r = s321Pick([2, 3, 4]);
        const s = r + 2;
        const sum = r + s;
        const prod = r * s;
        questions.push(`解不等式 \\(4^x-${sum}\\cdot2^x+${prod}>0\\)。`);
        answers.push(`簡答：\\(x<\\log_2 ${r}\\) 或 \\(x>\\log_2 ${s}\\)。過程：令 \\(t=2^x>0\\)，得 \\((t-${r})(t-${s})>0\\)，所以 \\(t<${r}\\) 或 \\(t>${s}\\)，再轉回 \\(x\\)。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`解不等式 \\((\\frac{16}{25})^x+2(\\frac45)^x-3\\le0\\)。`);
        answers.push(`簡答：\\(x\\ge0\\)。過程：令 \\(t=(\\frac45)^x>0\\)，則 \\(t^2+2t-3\\le0\\)，得 \\(0<t\\le1\\)。因 \\(0<\\frac45<1\\)，\\((\\frac45)^x\\le1\\) 等價於 \\(x\\ge0\\)。`);
        continue;
      }
      if (mode === 3) {
        const left = s321Pick([1, 2]);
        const right = left + s321Pick([2, 3]);
        const sum = left + right;
        const prod = left * right;
        questions.push(`解不等式 \\((\\frac{1}{10})^{x^2-${sum}x+${prod}}\\ge1\\)。`);
        answers.push(`簡答：\\(${left}\\le x\\le ${right}\\)。過程：\\(1=(\\frac{1}{10})^0\\)，底數小於 1，所以指數需 \\(\\le0\\)。即 \\((x-${left})(x-${right})\\le0\\)，解得 \\(${left}\\le x\\le ${right}\\)。`);
        continue;
      }
      questions.push(`解連續不等式 \\(\\frac13<3^{2x-1}<27\\)。`);
      answers.push(`簡答：\\(0<x<2\\)。過程：把兩側都寫成 3 的次方，\\(3^{-1}<3^{2x-1}<3^3\\)，底數大於 1，不等號方向不變。`);
    }
    return { questions, answers };
  }

  function buildS321ApplicationSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const start = s321Pick([2, 3, 5]);
        const ratio = s321Pick([2, 3, 4]);
        questions.push(`某細菌每小時變為原來的 ${ratio} 倍，若初始有 ${start} 個，求 \\(t\\) 小時後的數量函數。`);
        answers.push(`簡答：\\(N(t)=${start}\\cdot${ratio}^t\\)。過程：每經過 1 小時乘上 ${ratio}，連續 \\(t\\) 次就是指數模型。`);
        continue;
      }
      if (mode === 1) {
        const half = s321Pick([2, 3, 5]);
        const start = s321Pick([400, 800, 1600]);
        questions.push(`某物質半衰期為 ${half} 小時，初始量為 ${start}，求 ${2 * half} 小時後剩餘量。`);
        answers.push(`簡答：${start / 4}。過程：${2 * half} 小時是 2 個半衰期，所以剩餘 \\(${start}(\\frac12)^2=${start / 4}\\)。`);
        continue;
      }
      if (mode === 2) {
        const p = s321Pick([10000, 20000, 50000]);
        const r = s321Pick([2, 3, 5]);
        questions.push(`本金 ${p} 元存入銀行，年利率 ${r}% 且每年複利一次，寫出 \\(n\\) 年後本利和公式。`);
        answers.push(`簡答：\\(${p}(1+\\frac{${r}}{100})^n\\)。過程：每年乘上 \\(1+\\frac{${r}}{100}\\)，連續 \\(n\\) 年即為複利模型。`);
        continue;
      }
      if (mode === 3) {
        const rate = s321Pick([70, 80, 90]);
        questions.push(`光線每通過一塊透明板會剩下原強度的 ${rate}%，求通過 \\(n\\) 塊後強度小於原來 \\(\\frac35\\) 的不等式。`);
        answers.push(`簡答：\\((\\frac{${rate}}{100})^n<\\frac35\\)。過程：每通過一塊就乘上 \\(\\frac{${rate}}{100}\\)，所以剩餘比例為 \\((\\frac{${rate}}{100})^n\\)，要小於原強度的 \\(\\frac35\\)。`);
        continue;
      }
      const start = s321Pick([200, 400, 800]);
      questions.push(`某藥物在血液中每 2 小時濃度減半，初始濃度為 ${start}，求 8 小時後濃度。`);
      answers.push(`簡答：${start / 16}。過程：8 小時是 4 個半衰期，濃度為 \\(${start}(\\frac12)^4=${start / 16}\\)。`);
    }
    return { questions, answers };
  }

  function buildS321GraphFeatureSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s321Pick([2, 3, 4, 5]);
      const mode = i % 5;
      if (mode === 0) {
        questions.push(`函數 \\(y=${a}^x\\) 是否通過 \\((0,1)\\)？水平漸近線為何？`);
        answers.push(`簡答：通過 \\((0,1)\\)，水平漸近線為 \\(y=0\\)。過程：代入 \\(x=0\\)，得 \\(${a}^0=1\\)；指數函數值永遠趨近但不等於 0。`);
        continue;
      }
      if (mode === 1) {
        questions.push(`判斷 \\(y=${a}^x\\) 是遞增還是遞減，並說明原因。`);
        answers.push(`簡答：遞增。過程：因為底數 ${a}>1，所以 \\(x\\) 增加時，\\(${a}^x\\) 也增加。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`求 \\(y=${a}^{x-2}+3\\) 的水平漸近線與通過點 \\((2,?)\\)。`);
        answers.push(`簡答：水平漸近線 \\(y=3\\)，通過 \\((2,4)\\)。過程：由 \\(y=${a}^{x-2}\\) 上移 3 得漸近線；代入 \\(x=2\\) 得 \\(${a}^0+3=4\\)。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`判斷 \\(\\frac{${a}^x+${a}^{-x}}{2}\\ge1\\) 是否恆成立。`);
        answers.push(`簡答：恆成立。過程：令 \\(t=${a}^x>0\\)，則 \\(\\frac{t+1/t}{2}\\ge1\\)，等號在 \\(t=1\\) 即 \\(x=0\\) 時成立。`);
        continue;
      }
      questions.push(`判斷 \\(y=${a}^x\\) 與反函數 \\(y=\\log_${a}x\\) 是否關於直線 \\(y=x\\) 對稱。`);
      answers.push(`簡答：是。過程：互為反函數的兩個圖形會關於直線 \\(y=x\\) 對稱。`);
    }
    return { questions, answers };
  }

  function buildS321GraphTransformSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s321Pick([2, 3, 4]);
      const h = s321Pick([1, 2, 3]);
      const k = s321Pick([-2, 1, 3]);
      const mode = i % 5;
      if (mode === 0) {
        const moveY = k > 0 ? `上移 ${k}` : `下移 ${Math.abs(k)}`;
        questions.push(`將 \\(y=${a}^x\\) 的圖形向右平移 ${h} 單位並${moveY}單位，求新函數。`);
        answers.push(`簡答：\\(y=${a}^{x-${h}}${s321Plus(k)}\\)。過程：向右平移把 \\(x\\) 換成 \\(x-${h}\\)，${moveY}表示整體${k > 0 ? `加 ${k}` : `減 ${Math.abs(k)}`}。`);
        continue;
      }
      if (mode === 1) {
        questions.push(`求 \\(y=${a}^x\\) 關於 \\(y\\) 軸對稱後的函數式。`);
        answers.push(`簡答：\\(y=${a}^{-x}\\)。過程：關於 \\(y\\) 軸對稱時，把 \\(x\\) 換成 \\(-x\\)。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`求 \\(y=${a}^x\\) 以原點為對稱中心後的函數式。`);
        answers.push(`簡答：\\(y=-${a}^{-x}\\)。過程：原點對稱等於先 \\(x\\to -x\\)，再 \\(y\\to -y\\)。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`描述 \\(y=${a}^{|x|}\\) 的圖形特徵。`);
        answers.push(`簡答：關於 \\(y\\) 軸對稱，且最低點為 \\((0,1)\\)。過程：\\(|x|\\) 使左右兩側都取 \\(y=${a}^{|x|}\\)，所以圖形左右對稱。`);
        continue;
      }
      questions.push(`已知 \\(y=3^x\\) 平移後通過 \\((0,5)\\)、\\((1,11)\\)，求平移後的函數式。`);
      answers.push(`簡答：\\(y=3^{x+1}+2\\)。過程：設 \\(y=3^{x-h}+k\\)。代入兩點可得 \\(3^{-h}+k=5\\)、\\(3^{1-h}+k=11\\)，相減得 \\(2\\cdot3^{-h}=6\\)，故 \\(h=-1,k=2\\)。`);
    }
    return { questions, answers };
  }

  function buildS321CompositeExtremaSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const h = s321Pick([2, 3, 4]);
        const c = s321Pick([5, 9, 18]);
        const min = c;
        const rightValue = 16 - 4 * h + h * h + c;
        const maxText = s321Fraction(rightValue, 1);
        questions.push(`求 \\(f(x)=4^x-${2 * h}\\cdot2^x+${h * h + c}\\) 在區間 \\([-2,2]\\) 內的最大值與最小值。`);
        answers.push(`簡答：最小值 ${min}，最大值 ${maxText}。過程：令 \\(t=2^x\\)，則 \\(t\\in[\\frac14,4]\\)，且 \\(f(t)=(t-${h})^2+${c}\\)。頂點 \\(t=${h}\\) 在區間內，所以最小值為 ${min}；端點代入 \\(t=\\frac14,4\\) 比較得最大值 ${maxText}。`);
        continue;
      }
      if (mode === 1) {
        const h = s321Pick([2, 3, 4]);
        const c = s321Pick([7, 9, 12]);
        questions.push(`求 \\(y=-(\\frac19)^x+${2 * h}(\\frac13)^x+${c - h * h}\\) 在 \\([-2,1]\\) 上的最大值。`);
        answers.push(`簡答：${c}。過程：令 \\(t=(\\frac13)^x\\)，則 \\(t\\in[\\frac13,9]\\)，原式為 \\(-t^2+${2 * h}t+${c - h * h}=-(t-${h})^2+${c}\\)。因 ${h} 在區間內，所以最大值為 ${c}。`);
        continue;
      }
      if (mode === 2) {
        const h = s321Pick([1, 2, 3]);
        const c = s321Pick([4, 6, 8]);
        questions.push(`給定 \\(f(x)=9^x-${2 * h}\\cdot3^x+${h * h + c}\\)，求其最小值。`);
        answers.push(`簡答：${c}。過程：令 \\(t=3^x>0\\)，則 \\(f=t^2-${2 * h}t+${h * h + c}=(t-${h})^2+${c}\\)。因 \\(t=${h}>0\\) 可達，所以最小值為 ${c}。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`求 \\(a^x+a^{-x}\\) 的最小值與此時 \\(x\\) 的值，其中 \\(a>1\\)。`);
        answers.push(`簡答：最小值 2，於 \\(x=0\\) 時取得。過程：令 \\(t=a^x>0\\)，則 \\(t+\\frac1t\\ge2\\)。`);
        continue;
      }
      const total = s321Pick([6, 8, 10]);
      const min = 2 * Math.pow(3, total / 2);
      questions.push(`若點 \\((x,y)\\) 在直線 \\(x+2y=${total}\\) 上，求 \\(3^x+9^y\\) 的最小值。`);
      answers.push(`簡答：${min}。過程：由 \\(x=${total}-2y\\)，原式為 \\(3^{${total}-2y}+3^{2y}\\)。令 \\(t=3^{2y}>0\\)，成 \\(\\frac{3^{${total}}}{t}+t\\)，由 AM-GM 得最小值 \\(2\\sqrt{3^{${total}}}=${min}\\)。`);
    }
    return { questions, answers };
  }

  function buildS321AdvancedInequalitySet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const k = s321Pick([4, 6, 8, 10]);
        const min = 2 * Math.pow(3, k / 2);
        questions.push(`已知 \\(a+b=${k}\\)，求 \\(3^a+3^b\\) 的最小值。`);
        answers.push(`簡答：${min}。過程：令 \\(u=3^a,v=3^b\\)，則 \\(uv=3^{${k}}\\)。由 AM-GM，\\(u+v\\ge2\\sqrt{uv}=2\\cdot3^{${k / 2}}=${min}\\)，等號在 \\(a=b=${k / 2}\\)。`);
        continue;
      }
      if (mode === 1) {
        const base = s321Pick([2, 3, 5]);
        questions.push(`求 \\(y=${base}^x+${base}^{-x}\\) 的最小值，並求此時 \\(x\\) 的值。`);
        answers.push(`簡答：最小值 2，於 \\(x=0\\) 時取得。過程：令 \\(t=${base}^x>0\\)，則 \\(y=t+\\frac1t\\ge2\\)，等號在 \\(t=1\\)，也就是 \\(x=0\\)。`);
        continue;
      }
      if (mode === 2) {
        const k = s321Pick([1, 2, 3]);
        const min = Math.pow(3, 2 * k);
        questions.push(`求 \\(27^{x^2+${s321Fraction(2 * k, 3)}}\\) 的最小值。`);
        answers.push(`簡答：${min}。過程：底數 27 大於 1，指數愈小值愈小；\\(x^2\\ge0\\)，故指數最小為 \\(\\frac{${2 * k}}{3}\\)，最小值 \\(27^{${s321Fraction(2 * k, 3)}}=${min}\\)。`);
        continue;
      }
      if (mode === 3) {
        const k = s321Pick([8, 10, 12]);
        questions.push(`已知 \\(a+b=${k}\\)，求 \\(2^a+2^b\\) 的最小值。`);
        answers.push(`簡答：\\(${2 * Math.pow(2, k / 2)}\\)。過程：令 \\(u=2^a,v=2^b\\)，則 \\(uv=2^{${k}}\\)。由 AM-GM 得 \\(u+v\\ge2\\cdot2^{${k / 2}}\\)，等號在 \\(a=b=${k / 2}\\)。`);
        continue;
      }
      const c = s321Pick([2, 3, 4]);
      questions.push(`設 \\(2^x+2^{-x}=t\\)，將 \\(4^x+4^{-x}\\) 表為 \\(t\\) 的多項式，並求 \\(t=${c}\\) 時的值。`);
      answers.push(`簡答：\\(t^2-2\\)，代入得 ${c * c - 2}。過程：\\((2^x+2^{-x})^2=4^x+2+4^{-x}\\)，所以 \\(4^x+4^{-x}=t^2-2\\)。`);
    }
    return { questions, answers };
  }

  function buildS321AdvancedComparisonSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        questions.push(`比較 \\((0.7)^{${formatFraction(3, 2)}}\\)、\\((0.7)^2\\)、\\((0.7)^{-1}\\) 的大小。`);
        answers.push(`簡答：\\((0.7)^{-1}>(0.7)^{${formatFraction(3, 2)}}>(0.7)^2\\)。過程：底數介於 0 與 1 時，指數愈大值愈小；比較指數 \\(-1<\\frac32<2\\)。`);
        continue;
      }
      if (mode === 1) {
        const a = s321Pick([2, 3, 5]);
        questions.push(`給予相同指數 \\(\\frac12\\)，比較 \\(2^{${formatFraction(1, 2)}}\\)、\\(3^{${formatFraction(1, 2)}}\\)、\\(5^{${formatFraction(1, 2)}}\\) 的大小。`);
        answers.push(`簡答：\\(5^{${formatFraction(1, 2)}}>3^{${formatFraction(1, 2)}}>2^{${formatFraction(1, 2)}}\\)。過程：指數 \\(\\frac12>0\\)，底數愈大，值愈大。`);
        continue;
      }
      if (mode === 2) {
        const p = s321Pick([2, 3, 4]);
        questions.push(`若 \\(0<a<1\\)，比較 \\(a^2,a^3,a^{${formatFraction(1, p)}}\\) 的大小。`);
        answers.push(`簡答：\\(a^{${formatFraction(1, p)}}>a^2>a^3\\)。過程：底數介於 0 與 1，指數愈大值愈小。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`比較 \\((\\sqrt2)^3\\) 與 \\((\\sqrt3)^2\\) 的大小。`);
        answers.push(`簡答：\\((\\sqrt2)^3<(\\sqrt3)^2\\)。過程：兩數皆正，平方比較得 \\(((\\sqrt2)^3)^2=8\\)、\\(((\\sqrt3)^2)^2=9\\)，所以後者較大。`);
        continue;
      }
      questions.push(`判斷方程式 \\(2^x=x+3\\) 的實根個數。`);
      answers.push(`簡答：2 個。過程：令 \\(F(x)=2^x-x-3\\)。\\(F(-3)>0,F(-2)<0\\)，故 \\((-3,-2)\\) 有一根；\\(F(1)<0,F(2)>0\\)，故 \\((1,2)\\) 有一根。又 \\(F''(x)=(\\ln2)^2 2^x>0\\)，凸函數至多有兩個零點，所以共 2 根。`);
    }
    return { questions, answers };
  }

  function buildS321FunctionalEquationSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s321Pick([2, 3, 5]);
      const mode = i % 5;
      if (mode === 0) {
        questions.push(`設 \\(f(x)=${a}^x\\)，判斷 \\(f(x+y)=f(x)f(y)\\) 是否恆成立。`);
        answers.push(`簡答：成立。過程：\\(${a}^{x+y}=${a}^x\\cdot${a}^y\\)，這是指數函數的核心性質。`);
        continue;
      }
      if (mode === 1) {
        const k = s321Pick([2, 3, 4]);
        questions.push(`若 \\(f(x)=a^x\\) 且 \\(f(${k})=${Math.pow(a, k)}\\)，求 \\(f(-${k})\\)。`);
        answers.push(`簡答：\\(${formatFraction(1, Math.pow(a, k))}\\)。過程：\\(f(-${k})=a^{-${k}}=\\frac1{a^${k}}\\)。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`證明對任意實數 \\(x_1,x_2\\)，\\(f(x_1+x_2)=f(x_1)f(x_2)\\)，其中 \\(f(x)=a^x\\)。`);
        answers.push(`簡答：成立。過程：依指數律 \\(a^{x_1+x_2}=a^{x_1}a^{x_2}\\)。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`判斷指數函數 \\(f(x)=a^x\\) 是否為一對一函數。`);
        answers.push(`簡答：是。過程：當 \\(a>1\\) 時遞增，當 \\(0<a<1\\) 時遞減，兩種情況皆單調，所以一對一。`);
        continue;
      }
      questions.push(`若 \\(f(x)=a^x\\)、\\(f(k)=125\\)，求 \\(f(-k)\\)。`);
      answers.push(`簡答：\\(\\frac1{125}\\)。過程：\\(f(k)f(-k)=a^k a^{-k}=1\\)。`);
    }
    return { questions, answers };
  }

  function buildS321SymmetricExpressionSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        const t = s321Pick([3, 4, 5]);
        questions.push(`已知 \\(a^x+a^{-x}=${t}\\)，求 \\(a^{2x}+a^{-2x}\\)。`);
        answers.push(`簡答：${t * t - 2}。過程：平方得 \\((a^x+a^{-x})^2=a^{2x}+2+a^{-2x}\\)，所以答案為 \\(${t}^2-2\\)。`);
        continue;
      }
      if (mode === 1) {
        const t = s321Pick([3, 4]);
        questions.push(`令 \\(t=a^x+a^{-x}\\)，以 \\(t\\) 表示 \\(a^{3x}+a^{-3x}\\)。`);
        answers.push(`簡答：\\(t^3-3t\\)。過程：利用 \\((u+v)^3=u^3+v^3+3uv(u+v)\\)，其中 \\(uv=1\\)。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`解方程式 \\(2(4^x+4^{-x})-9(2^x+2^{-x})+14=0\\)。`);
        answers.push(`簡答：令 \\(t=2^x+2^{-x}\\)，轉為二次方程。過程：\\(4^x+4^{-x}=t^2-2\\)，代入後解 \\(2(t^2-2)-9t+14=0\\)，且需 \\(t\\ge2\\)。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`已知 \\(a^{1/2}+a^{-1/2}=\\sqrt5\\)，求 \\(a+a^{-1}\\)。`);
        answers.push(`簡答：3。過程：平方得 \\(a+2+a^{-1}=5\\)，所以 \\(a+a^{-1}=3\\)。`);
        continue;
      }
      questions.push(`已知 \\(a^{2x}=5\\)，計算 \\(\\frac{a^{3x}+a^{-3x}}{a^x+a^{-x}}\\)。`);
      answers.push(`簡答：\\(\\sqrt5+\\frac1{\\sqrt5}-1\\)。過程：令 \\(u=a^x\\)，則 \\(u^2=5\\)，用 \\(u^3+u^{-3}=(u+u^{-1})(u^2+u^{-2}-1)\\)。`);
    }
    return { questions, answers };
  }

  function buildS321HyperbolicFunctionSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const a = s321Pick([2, 3, 5]);
      const mode = i % 5;
      if (mode === 0) {
        questions.push(`設 \\(f(x)=\\frac{${a}^x-${a}^{-x}}{${a}^x+${a}^{-x}}\\)，證明 \\(f(-x)=-f(x)\\)。`);
        answers.push(`簡答：是奇函數。過程：把 \\(-x\\) 代入後，分子變號、分母不變，所以 \\(f(-x)=-f(x)\\)。`);
        continue;
      }
      if (mode === 1) {
        questions.push(`求 \\(f(x)=\\frac{${a}^x+${a}^{-x}}{${a}^x-${a}^{-x}}\\) 的定義域。`);
        answers.push(`簡答：\\(x\\ne0\\)。過程：分母為 0 時 \\(${a}^x=${a}^{-x}\\)，得 \\(x=0\\)，需排除。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`若 \\(f(x)=\\frac{${a}^x-${a}^{-x}}{2}\\)，求 \\(f(0)\\)。`);
        answers.push(`簡答：0。過程：代入 \\(x=0\\)，分子為 \\(1-1=0\\)。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`若 \\(g(x)=\\frac{${a}^x+${a}^{-x}}{2}\\)，求其最小值。`);
        answers.push(`簡答：1。過程：令 \\(t=${a}^x>0\\)，\\(\\frac{t+1/t}{2}\\ge1\\)，等號在 \\(t=1\\)。`);
        continue;
      }
      questions.push(`設 \\(f(x)=\\frac{${a}^{2x}-${a}^{-2x}}{2}\\)，用 \\(f(x)\\) 的想法說明其奇偶性。`);
      answers.push(`簡答：奇函數。過程：代入 \\(-x\\) 後，兩項互換並整體變號。`);
    }
    return { questions, answers };
  }

  function buildS321IntersectionRootCountSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        questions.push(`判定方程式 \\(2^x=x^2\\) 有幾個實數解。`);
        answers.push(`簡答：3 個。過程：觀察 \\(y=2^x\\) 與 \\(y=x^2\\) 的交點，可由圖形與代入區間判定共有 3 個。`);
        continue;
      }
      if (mode === 1) {
        questions.push(`判定方程式 \\(10^x=x\\) 有幾個實根。`);
        answers.push(`簡答：0 個。過程：若 \\(x\\le0\\)，左式正而右式非正；若 \\(x>0\\)，\\(10^x>x\\)，所以無解。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`求 \\(y=2^x\\) 與 \\(y=x^2\\) 的圖形交點個數。`);
        answers.push(`簡答：3 個。過程：等同判斷方程 \\(2^x=x^2\\)，可用圖形或符號變化分區判斷。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`判定 \\((\\frac12)^x=x+1\\) 的實根個數。`);
        answers.push(`簡答：1 個。過程：左式 \\((\\frac12)^x\\) 遞減，右式 \\(x+1\\) 遞增，因此至多一個交點；代入 \\(x=0\\) 成立，所以恰有 1 個實根。`);
        continue;
      }
      questions.push(`利用圖形判定 \\(2^x=-x+2\\) 有幾個解。`);
      answers.push(`簡答：1 個。過程：令 \\(F(x)=2^x+x-2\\)，則 \\(F'(x)=(\\ln2)2^x+1>0\\)，所以 \\(F\\) 嚴格遞增；又 \\(F(0)=-1,F(1)=1\\)，因此恰有 1 個實根。`);
    }
    return { questions, answers };
  }

  function buildS321ParameterFromGraphSet(count) {
    const questions = [];
    const answers = [];
    for (let i = 0; i < count; i += 1) {
      const mode = i % 5;
      if (mode === 0) {
        questions.push(`函數 \\(y=c\\cdot a^x+k\\) 通過 \\((0,0),(1,4),(-1,-\\frac43)\\)，求 \\(a,c,k\\)。`);
        answers.push(`簡答：\\(a=3,c=3,k=-3\\)。過程：代入三點得 \\(c+k=0\\)、\\(ca+k=4\\)、\\(c/a+k=-\\frac43\\)，解聯立可得。`);
        continue;
      }
      if (mode === 1) {
        questions.push(`已知指數函數通過 \\((0,16)\\) 與 \\((1,8)\\)，求形如 \\(y=C\\cdot r^x\\) 的函數式。`);
        answers.push(`簡答：\\(y=16(\\frac12)^x\\)。過程：代入 \\(x=0\\) 得 \\(C=16\\)，再由 \\(16r=8\\) 得 \\(r=\\frac12\\)。`);
        continue;
      }
      if (mode === 2) {
        questions.push(`某細菌在 2 天後有 20000 個，3.5 天後有 160000 個，求其增殖倍率模型的底數。`);
        answers.push(`簡答：每日倍率為 4。過程：設 \\(N(t)=C a^t\\)，兩式相除得 \\(a^{1.5}=8\\)，所以 \\(a=4\\)。`);
        continue;
      }
      if (mode === 3) {
        questions.push(`已知一指數圖形的水平漸近線為 \\(y=-2\\)，且通過 \\((0,0)\\)，寫出一個可能的解析式。`);
        answers.push(`簡答：例如 \\(y=2\\cdot2^x-2\\)。過程：設 \\(y=C a^x-2\\)，代入 \\((0,0)\\) 得 \\(C-2=0\\)，所以 \\(C=2\\)。取 \\(a=2\\) 可得一個可能式 \\(y=2\\cdot2^x-2\\)。`);
        continue;
      }
      questions.push(`已知 \\(y=a^x\\) 通過 \\((2,9)\\)，求 \\(y=27\\) 對應的 \\(x\\)。`);
      answers.push(`簡答：3。過程：由 \\(a^2=9\\) 且 \\(a>0\\)，得 \\(a=3\\)。所以 \\(3^x=27\\)，\\(x=3\\)。`);
    }
    return { questions, answers };
  }

